let settings=JSON.parse(localStorage.getItem('pet_settings')||'null')||structuredClone(DEFAULT_SETTINGS);if(!settings.name||settings.name==="Patitas O'Higgins"){settings.name="The Loki & Molly World's";}if(!settings.logoImage){settings.logoImage=DEFAULT_SETTINGS.logoImage;}if(!settings.heroImage||String(settings.heroImage).includes("images.unsplash.com/photo-1450778869180-41d0601e046e")){settings.heroImage=DEFAULT_SETTINGS.heroImage;}let products=JSON.parse(localStorage.getItem('pet_products')||'null')||structuredClone(DEFAULT_PRODUCTS);let tips=JSON.parse(localStorage.getItem('pet_tips')||'null')||structuredClone(DEFAULT_TIPS);let cart=[];let filter='Todos';let tipFilter='Todos';let dailyTipOffset=0;
let smartMembers=JSON.parse(localStorage.getItem('pet_members')||'{}');let currentMemberRut=sessionStorage.getItem('pet_current_member')||'';let foundations=JSON.parse(localStorage.getItem('pet_foundations')||'null')||structuredClone(DEFAULT_FOUNDATIONS);
const money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(Number(n)||0);const esc=s=>String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
function persist(){localStorage.setItem('pet_settings',JSON.stringify(settings));localStorage.setItem('pet_products',JSON.stringify(products));localStorage.setItem('pet_tips',JSON.stringify(tips));localStorage.setItem('pet_members',JSON.stringify(smartMembers));localStorage.setItem('pet_foundations',JSON.stringify(foundations))}
function applySettings(){document.documentElement.style.setProperty('--brand',settings.brand);document.documentElement.style.setProperty('--brand2',settings.brand2);document.getElementById('storeNameNav').innerHTML=esc(settings.name);document.getElementById('storeNameFooter').textContent=settings.name;document.getElementById('copyrightName').textContent=settings.name;document.getElementById('heroTitle').textContent=settings.heroTitle;document.getElementById('heroText').textContent=settings.heroText;document.getElementById('heroCard').style.backgroundImage=`linear-gradient(120deg,rgba(21,34,56,.88),rgba(255,95,109,.68)),url("${settings.heroImage}")`;['storeLogoNav','storeLogoHero','brandStoryLogo','storeLogoFooter'].forEach(id=>{const el=document.getElementById(id);if(el)el.src=settings.logoImage||DEFAULT_SETTINGS.logoImage});const showcase=document.getElementById('brandShowcaseImage');if(showcase)showcase.src=settings.heroImage||DEFAULT_SETTINGS.heroImage;document.getElementById('hoursText').textContent=settings.hours;document.getElementById('phoneText').textContent='WhatsApp: +'+settings.whatsapp;const url='https://wa.me/'+settings.whatsapp+'?text='+encodeURIComponent('Hola, quiero consultar por productos para mi mascota');document.getElementById('heroWhatsApp').href=url;document.getElementById('floatingWhatsApp').href=url;document.title=settings.name+' | Tienda para mascotas'}
function render(){applySettings();renderTips();renderSmartBuy();renderFoundations();const q=document.getElementById('search').value.toLowerCase();const cats=['Todos',...new Set(products.map(p=>p.cat).filter(Boolean))];document.getElementById('chips').innerHTML=cats.map(c=>`<button class="chip ${c===filter?'active':''}" onclick="setFilter('${esc(c)}')">${esc(c)}</button>`).join('');const visible=products.filter(p=>(filter==='Todos'||p.cat===filter)&&p.name.toLowerCase().includes(q));document.getElementById('grid').innerHTML=visible.length?visible.map(p=>`<article class="product"><div class="label">${esc(p.label||'Destacado')}</div><div class="product-img">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" onerror="this.outerHTML='<div class=\'fallback\'>${esc(p.emoji||'🐾')}</div>'">`:`<div class="fallback">${esc(p.emoji||'🐾')}</div>`}</div><h3>${esc(p.name)}</h3><div class="meta">${esc(p.cat)}</div><div class="price">${money(p.price)}</div><div class="stock ${p.stock<=4?'low':''}">${p.stock>0?`Disponible · ${p.stock} unidades`:'Sin stock'}</div><div class="product-actions"><button class="btn btn-primary" ${p.stock<1?'disabled':''} onclick="addCart(${p.id})">Agregar</button><button class="btn btn-outline" onclick="askWhatsApp(${p.id})">Consultar</button></div></article>`).join(''):'<p>No hay productos que coincidan con la búsqueda.</p>';renderCart();renderAdminTable()}

function renderTips(){const filters=['Todos','Perro','Gato','Alimentación','Ejercicio','Rutina','Bienestar emocional'];document.getElementById('tipFilters').innerHTML=filters.map(f=>`<button class="chip ${f===tipFilter?'active':''}" onclick="setTipFilter('${esc(f)}')">${esc(f)}</button>`).join('');const shown=tips.filter(t=>tipFilter==='Todos'||t.pet===tipFilter||t.pet==='Ambos'&&(tipFilter==='Perro'||tipFilter==='Gato')||t.category===tipFilter);document.getElementById('tipsGrid').innerHTML=shown.length?shown.map(t=>`<article class="tip-card"><div class="tip-image">${t.image?`<img src="${esc(t.image)}" alt="${esc(t.title)}">`:esc(t.emoji||'🐾')}</div><div class="tip-body"><span class="tip-type">${esc(t.pet)} · ${esc(t.category)}</span><h4>${esc(t.title)}</h4><p>${esc(t.text)}</p>${t.brand?`<div class="tip-brand">🛒 ${esc(t.brand)}</div>`:''}</div></article>`).join(''):'<div class="tips-empty">No hay consejos en esta categoría.</div>';const pool=shown.length?shown:tips;if(pool.length){const day=Math.floor(Date.now()/86400000);const t=pool[(day+dailyTipOffset)%pool.length];document.getElementById('dailyTip').innerHTML=`<div class="daily-tip-visual">${t.image?`<img src="${esc(t.image)}" alt="${esc(t.title)}">`:esc(t.emoji||'🐾')}</div><div><div class="eyebrow">Consejo saludable del día</div><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p>${t.brand?`<div style="margin-top:10px;color:#ffe28b;font-weight:800">Producto relacionado: ${esc(t.brand)}</div>`:''}</div>`;}renderAdminTips()}
function setTipFilter(f){tipFilter=f;dailyTipOffset=0;renderTips()}function showAnotherTip(){dailyTipOffset++;renderTips()}
async function saveTip(){const title=tTitle.value.trim(),text=tText.value.trim();if(!title||!text)return alert('Completa el título y el consejo.');const id=Number(editTipId.value)||Date.now();const old=tips.find(t=>t.id===id);const img=await fileToDataURL(tImage.files[0]);const tip={id,title,pet:tPet.value,category:tCategory.value,text,brand:tBrand.value.trim(),emoji:tEmoji.value.trim()||'🐾',image:img||(old&&old.image)||''};if(old)tips=tips.map(t=>t.id===id?tip:t);else tips.unshift(tip);persist();clearTipForm();renderTips();alert('Consejo guardado.')}
function renderAdminTips(){const body=document.getElementById('adminTips');if(!body)return;body.innerHTML=tips.map(t=>`<tr><td>${t.image?`<img class="thumb" src="${esc(t.image)}">`:`<div class="thumb" style="display:grid;place-items:center">${esc(t.emoji||'🐾')}</div>`}</td><td><strong>${esc(t.title)}</strong><br><small>${esc(t.brand||'')}</small></td><td>${esc(t.pet)}</td><td>${esc(t.category)}</td><td><div class="mini-actions"><button onclick="editTip(${t.id})">Editar</button><button onclick="deleteTip(${t.id})">Eliminar</button></div></td></tr>`).join('')}
function editTip(id){const t=tips.find(x=>x.id===id);editTipId.value=t.id;tTitle.value=t.title;tPet.value=t.pet;tCategory.value=t.category;tText.value=t.text;tBrand.value=t.brand||'';tEmoji.value=t.emoji||'';tipFormTitle.textContent='Editar consejo'}function deleteTip(id){if(!confirm('¿Eliminar este consejo?'))return;tips=tips.filter(t=>t.id!==id);persist();renderTips()}function clearTipForm(){editTipId.value='';tTitle.value='';tPet.value='Perro';tCategory.value='Alimentación';tText.value='';tBrand.value='';tEmoji.value='';tImage.value='';tipFormTitle.textContent='Agregar consejo'}

function renderFoundations(){
  const grid=document.getElementById('foundationGrid'),select=document.getElementById('donationFoundation');if(!grid||!select)return;
  grid.innerHTML=foundations.length?foundations.map(f=>`<article class="foundation-card"><div class="foundation-logo">${f.image?`<img src="${esc(f.image)}" alt="${esc(f.name)}">`:esc(f.emoji||'🐾')}</div><h4>${esc(f.name)}</h4><p>${esc(f.description||'Organización de protección animal.')}</p><div class="foundation-meta"><span>📍 ${esc(f.commune||'Región de O\'Higgins')}</span><span>🎁 Necesita: ${esc(f.needs||'Aportes coordinados')}</span><span>${f.verified?'✅ Organización verificada':'🟡 Pendiente de verificación'}</span></div><div class="foundation-actions">${f.whatsapp?`<button class="btn btn-primary" onclick="contactFoundation(${f.id})">Contactar</button>`:''}${f.web?`<a class="btn btn-outline" href="${esc(f.web)}" target="_blank" rel="noopener">Conocer más</a>`:''}<button class="btn btn-outline" onclick="selectDonationFoundation(${f.id})">Donar</button></div></article>`).join(''):'<div class="foundation-empty">Próximamente publicaremos organizaciones aliadas de la región.</div>';
  select.innerHTML=foundations.map(f=>`<option value="${f.id}">${esc(f.name)} — ${esc(f.commune||'O\'Higgins')}</option>`).join('');
}
function selectDonationFoundation(id){const s=document.getElementById('donationFoundation');if(s)s.value=String(id);document.getElementById('alianzas').scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>document.getElementById('donationDetail').focus(),500)}
function contactFoundation(id){const f=foundations.find(x=>x.id===id);if(!f||!f.whatsapp)return alert('Esta organización aún no tiene WhatsApp publicado.');window.open('https://wa.me/'+f.whatsapp.replace(/\D/g,'')+'?text='+encodeURIComponent(`Hola, vi su alianza en ${settings.name} y quiero conocer cómo ayudar.`),'_blank')}
function sendDonationRequest(){const f=foundations.find(x=>String(x.id)===document.getElementById('donationFoundation').value);if(!f)return alert('Selecciona una organización.');const type=document.getElementById('donationType').value,detail=document.getElementById('donationDetail').value.trim(),msg=document.getElementById('donationMessage').value.trim();const text=`Hola, quiero coordinar una donación mediante ${settings.name}.\n\nOrganización: ${f.name}\nTipo de aporte: ${type}\nDetalle: ${detail||'Por definir'}\nMensaje: ${msg||'Sin mensaje adicional'}\n\nSolicito confirmar recepción, fecha y lugar de entrega.`;window.open('https://wa.me/'+settings.whatsapp+'?text='+encodeURIComponent(text),'_blank')}
async function saveFoundation(){const name=fName.value.trim(),commune=fCommune.value.trim();if(!name||!commune)return alert('Completa el nombre y la comuna.');const id=Number(editFoundationId.value)||Date.now();const old=foundations.find(f=>f.id===id);const img=await fileToDataURL(fImage.files[0]);const item={id,name,commune,description:fDescription.value.trim(),needs:fNeeds.value.trim(),whatsapp:fWhatsapp.value.replace(/\D/g,''),web:fWeb.value.trim(),emoji:fEmoji.value.trim()||'🐾',image:img||(old&&old.image)||'',verified:old?!!old.verified:false};if(old)foundations=foundations.map(f=>f.id===id?item:f);else foundations.unshift(item);persist();clearFoundationForm();render();renderAdminTable();alert('Alianza guardada. Verifica sus datos antes de publicarla como organización confirmada.')}
function clearFoundationForm(){editFoundationId.value='';fName.value='';fCommune.value='';fDescription.value='';fNeeds.value='';fWhatsapp.value='';fWeb.value='';fEmoji.value='';fImage.value='';foundationFormTitle.textContent='Agregar alianza solidaria'}
function editFoundation(id){const f=foundations.find(x=>x.id===id);if(!f)return;editFoundationId.value=f.id;fName.value=f.name;fCommune.value=f.commune||'';fDescription.value=f.description||'';fNeeds.value=f.needs||'';fWhatsapp.value=f.whatsapp||'';fWeb.value=f.web||'';fEmoji.value=f.emoji||'';foundationFormTitle.textContent='Editar alianza solidaria'}
function toggleFoundationVerified(id){foundations=foundations.map(f=>f.id===id?{...f,verified:!f.verified}:f);persist();render();renderAdminTable()}
function deleteFoundation(id){if(!confirm('¿Eliminar esta alianza?'))return;foundations=foundations.filter(f=>f.id!==id);persist();render();renderAdminTable()}

function setFilter(c){filter=c;render()}function addCart(id){const p=products.find(x=>x.id===id);if(!p)return;const item=cart.find(x=>x.id===id);if(item&&item.qty<p.stock)item.qty++;else if(!item&&p.stock>0)cart.push({...p,qty:1});renderCart()}
function renderCart(){const count=cart.reduce((a,i)=>a+i.qty,0),total=cart.reduce((a,i)=>a+i.price*i.qty,0);document.getElementById('cartCount').textContent=count;document.getElementById('cartItems').innerHTML=cart.length?cart.map(i=>`<div class="cart-item"><div><strong>${esc(i.name)}</strong><div class="meta">${money(i.price)} c/u</div><div class="qty"><button onclick="changeQty(${i.id},-1)">−</button><span>${i.qty}</span><button onclick="changeQty(${i.id},1)">+</button></div></div><button class="btn btn-outline" onclick="removeCart(${i.id})">Quitar</button></div>`).join(''):'<p class="meta">Tu carrito está vacío.</p>';document.getElementById('subtotal').textContent=money(total);document.getElementById('cartTotal').textContent=money(total)}
function changeQty(id,d){const i=cart.find(x=>x.id===id);if(!i)return;i.qty=Math.max(1,Math.min(i.stock,i.qty+d));renderCart()}function removeCart(id){cart=cart.filter(i=>i.id!==id);renderCart()}function toggleCart(){document.getElementById('drawer').classList.toggle('open');document.getElementById('overlay').classList.toggle('show')}
function checkout(){if(!cart.length)return alert('Tu carrito está vacío.');recordSmartOrder();alert('Pedido registrado como demostración. Aquí se conectará WebPay o Mercado Pago cuando la tienda sea publicada.')}function checkoutWhatsApp(){if(!cart.length)return alert('Tu carrito está vacío.');recordSmartOrder();const total=cart.reduce((a,i)=>a+i.price*i.qty,0);const text='Hola, quiero realizar este pedido:\n'+cart.map(i=>`- ${i.qty} x ${i.name}`).join('\n')+`\n\nTotal productos: ${money(total)}\nComuna de entrega:`;window.open('https://wa.me/'+settings.whatsapp+'?text='+encodeURIComponent(text),'_blank')}function askWhatsApp(id){const p=products.find(x=>x.id===id);window.open('https://wa.me/'+settings.whatsapp+'?text='+encodeURIComponent('Hola, quiero consultar por '+p.name),'_blank')}function openSubscription(){window.open('https://wa.me/'+settings.whatsapp+'?text='+encodeURIComponent('Hola, quiero información sobre la suscripción mensual.'),'_blank')}

function normalizeRut(v){return String(v||'').replace(/[^0-9kK]/g,'').toUpperCase()}
function formatRut(v){const r=normalizeRut(v);if(r.length<2)return r;const body=r.slice(0,-1),dv=r.slice(-1);return body.replace(/\B(?=(\d{3})+(?!\d))/g,'.')+'-'+dv}
function validRut(v){const r=normalizeRut(v);if(r.length<8)return false;let body=r.slice(0,-1),dv=r.slice(-1),sum=0,m=2;for(let i=body.length-1;i>=0;i--){sum+=Number(body[i])*m;m=m===7?2:m+1}let calc=11-(sum%11);calc=calc===11?'0':calc===10?'K':String(calc);return calc===dv}
function smartLogin(){const rut=normalizeRut(document.getElementById('smartRut').value);if(!validRut(rut))return alert('Ingresa un RUT válido.');if(!smartMembers[rut])return alert('No encontramos este RUT como socio. Puedes crearlo con el botón Crear socio.');currentMemberRut=rut;sessionStorage.setItem('pet_current_member',rut);document.getElementById('smartRut').value=formatRut(rut);renderSmartBuy()}
function createSmartMember(){const rut=normalizeRut(document.getElementById('smartRut').value),name=document.getElementById('smartName').value.trim();if(!validRut(rut))return alert('Ingresa un RUT válido.');if(!name)return alert('Ingresa el nombre del socio.');if(!smartMembers[rut])smartMembers[rut]={name,rut,createdAt:new Date().toISOString(),orders:[]};else smartMembers[rut].name=name;currentMemberRut=rut;sessionStorage.setItem('pet_current_member',rut);persist();document.getElementById('smartRut').value=formatRut(rut);renderSmartBuy();alert('Socio creado correctamente.')}
function smartLogout(){currentMemberRut='';sessionStorage.removeItem('pet_current_member');renderSmartBuy()}
function getMember(){return currentMemberRut&&smartMembers[currentMemberRut]?smartMembers[currentMemberRut]:null}
function recordSmartOrder(){const m=getMember();if(!m||!cart.length)return;const order={id:Date.now(),date:new Date().toISOString(),items:cart.map(i=>({id:i.id,name:i.name,qty:i.qty,price:i.price,cat:i.cat||''})),total:cart.reduce((a,i)=>a+i.price*i.qty,0)};m.orders.unshift(order);m.orders=m.orders.slice(0,30);persist();renderSmartBuy()}
function smartRecommendations(member){if(!member||!member.orders.length)return products.slice(0,6).map(p=>({p,reason:'Producto destacado para comenzar'}));const counts={},last={};member.orders.forEach((o,oi)=>o.items.forEach(i=>{counts[i.id]=(counts[i.id]||0)+i.qty;if(last[i.id]===undefined)last[i.id]=oi}));const bought=Object.keys(counts).map(Number).sort((a,b)=>counts[b]-counts[a]);const result=[];bought.forEach(id=>{const p=products.find(x=>x.id===id);if(p)result.push({p,reason:last[id]===0?'Comprado en tu último pedido':'Uno de tus productos habituales'})});const cats=new Set(result.map(x=>x.p.cat));products.filter(p=>!bought.includes(p.id)&&cats.has(p.cat)).slice(0,3).forEach(p=>result.push({p,reason:'Complementa tus compras habituales'}));return result.slice(0,6)}
function renderSmartBuy(){const status=document.getElementById('smartStatus'),grid=document.getElementById('smartGrid'),history=document.getElementById('smartHistory'),actions=document.getElementById('memberActions'),title=document.getElementById('smartTitle');if(!status||!grid)return;const m=getMember();if(!m){status.className='smart-status';status.textContent='Ingresa tu RUT para consultar tu historial de compras.';actions.classList.add('hidden');title.textContent='Recomendaciones para ti';grid.innerHTML='<div class="smart-empty">Identifícate para ver productos comprados anteriormente y recomendaciones.</div>';history.innerHTML='';return}status.className='smart-status active';status.textContent=`Socio activo: ${m.name} · ${formatRut(m.rut)} · ${m.orders.length} compra(s) registrada(s)`;actions.classList.remove('hidden');title.textContent=`Sugerencias para ${m.name}`;const recs=smartRecommendations(m);grid.innerHTML=recs.map(({p,reason})=>`<article class="smart-card"><div class="smart-thumb">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:esc(p.emoji||'🐾')}</div><div class="smart-reason">${esc(reason)}</div><h4>${esc(p.name)}</h4><div class="price">${money(p.price)}</div><button class="btn btn-primary" onclick="addCart(${p.id})" ${p.stock<1?'disabled':''}>Agregar</button></article>`).join('')||'<div class="smart-empty">Todavía no hay recomendaciones disponibles.</div>';history.innerHTML=m.orders.length?`<h3 style="margin-top:20px">Compras anteriores</h3><div class="history-list">${m.orders.slice(0,5).map(o=>`<div class="history-item"><span>${new Date(o.date).toLocaleDateString('es-CL')} · ${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join(', ')}</span><strong>${money(o.total)}</strong></div>`).join('')}</div>`:'<div class="smart-empty" style="margin-top:16px">Aún no hay compras registradas. Agrega productos al carrito y simula un pago o pedido por WhatsApp.</div>'}
function addPreviousPurchaseToCart(){const m=getMember();if(!m||!m.orders.length)return alert('Este socio aún no tiene compras anteriores.');m.orders[0].items.forEach(i=>{const p=products.find(x=>x.id===i.id);if(!p||p.stock<1)return;const existing=cart.find(x=>x.id===p.id);if(existing)existing.qty=Math.min(existing.qty+i.qty,p.stock);else cart.push({...p,qty:Math.min(i.qty,p.stock)})});renderCart();toggleCart()}

function openAdminLogin(){document.getElementById('adminLogin').classList.add('show');document.getElementById('adminPassword').value=''}function closeAdminLogin(){document.getElementById('adminLogin').classList.remove('show')}function loginAdmin(){if(document.getElementById('adminPassword').value!=='1234')return alert('Clave incorrecta.');closeAdminLogin();openAdminPanel()}function openAdminPanel(){loadSettingsForm();document.getElementById('adminPanel').classList.add('show');renderAdminTable()}function closeAdminPanel(){document.getElementById('adminPanel').classList.remove('show')}
function loadSettingsForm(){cfgName.value=settings.name;cfgWhatsapp.value=settings.whatsapp;cfgHeroTitle.value=settings.heroTitle;cfgHeroText.value=settings.heroText;cfgBrand.value=settings.brand;cfgBrand2.value=settings.brand2;cfgHours.value=settings.hours}
function fileToDataURL(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function saveSettings(){settings.name=cfgName.value.trim()||DEFAULT_SETTINGS.name;settings.whatsapp=cfgWhatsapp.value.replace(/\D/g,'')||DEFAULT_SETTINGS.whatsapp;settings.heroTitle=cfgHeroTitle.value.trim()||DEFAULT_SETTINGS.heroTitle;settings.heroText=cfgHeroText.value.trim()||DEFAULT_SETTINGS.heroText;settings.brand=cfgBrand.value;settings.brand2=cfgBrand2.value;settings.hours=cfgHours.value.trim()||DEFAULT_SETTINGS.hours;const logo=await fileToDataURL(cfgLogoImage.files[0]);if(logo)settings.logoImage=logo;const img=await fileToDataURL(cfgHeroImage.files[0]);if(img)settings.heroImage=img;persist();render();alert('Cambios guardados.')}
async function saveProduct(){const name=pName.value.trim(),cat=pCat.value.trim(),price=Number(pPrice.value),stock=Number(pStock.value);if(!name||!cat||price<0||stock<0)return alert('Completa nombre, categoría, precio y stock.');const id=Number(editId.value)||Date.now();const old=products.find(p=>p.id===id);const img=await fileToDataURL(pImage.files[0]);const product={id,name,cat,price,stock,label:pLabel.value.trim()||'Destacado',emoji:pEmoji.value.trim()||'🐾',image:img||(old&&old.image)||''};if(old)products=products.map(p=>p.id===id?product:p);else products.unshift(product);persist();clearProductForm();render();alert('Producto guardado.')}
function renderAdminTable(){const body=document.getElementById('adminProducts');if(!body)return;body.innerHTML=products.map(p=>`<tr><td>${p.image?`<img class="thumb" src="${esc(p.image)}">`:`<div class="thumb" style="display:grid;place-items:center">${esc(p.emoji||'🐾')}</div>`}</td><td><strong>${esc(p.name)}</strong><br><small>${esc(p.label||'')}</small></td><td>${esc(p.cat)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td><div class="mini-actions"><button onclick="editProduct(${p.id})">Editar</button><button onclick="deleteProduct(${p.id})">Eliminar</button></div></td></tr>`).join('');const fbody=document.getElementById('adminFoundations');if(fbody)fbody.innerHTML=foundations.map(f=>`<tr><td>${f.image?`<img class="thumb" src="${esc(f.image)}">`:`<div class="thumb" style="display:grid;place-items:center">${esc(f.emoji||'🐾')}</div>`}</td><td><strong>${esc(f.name)}</strong><br><small>${f.verified?'Verificada':'Pendiente'}</small></td><td>${esc(f.commune||'')}</td><td>${esc(f.needs||'')}</td><td><div class="mini-actions"><button onclick="editFoundation(${f.id})">Editar</button><button onclick="toggleFoundationVerified(${f.id})">${f.verified?'Quitar verificación':'Verificar'}</button><button onclick="deleteFoundation(${f.id})">Eliminar</button></div></td></tr>`).join('')}
function editProduct(id){const p=products.find(x=>x.id===id);editId.value=p.id;pName.value=p.name;pCat.value=p.cat;pPrice.value=p.price;pStock.value=p.stock;pLabel.value=p.label||'';pEmoji.value=p.emoji||'';formTitle.textContent='Editar producto';window.scrollTo({top:0,behavior:'smooth'})}function deleteProduct(id){if(!confirm('¿Eliminar este producto?'))return;products=products.filter(p=>p.id!==id);cart=cart.filter(p=>p.id!==id);persist();render()}function clearProductForm(){editId.value='';pName.value='';pCat.value='';pPrice.value='';pStock.value='';pLabel.value='';pEmoji.value='';pImage.value='';formTitle.textContent='Agregar producto'}function resetDemo(){if(!confirm('¿Restaurar todos los datos de demostración?'))return;settings=structuredClone(DEFAULT_SETTINGS);products=structuredClone(DEFAULT_PRODUCTS);tips=structuredClone(DEFAULT_TIPS);foundations=structuredClone(DEFAULT_FOUNDATIONS);persist();loadSettingsForm();clearProductForm();clearFoundationForm();render()}

document.addEventListener('input',e=>{if(e.target&&e.target.id==='smartRut'){const raw=normalizeRut(e.target.value);e.target.value=raw.length>1?formatRut(raw):raw}});
function initPawRails(){
  document.querySelectorAll('.paw-btn').forEach((btn,idx)=>{
    btn.style.setProperty('--rot',`${(idx%2===0?-8:8)+(idx%3===0?2:-2)}deg`);
    btn.style.animationDelay=`-${(idx%6)*0.55}s`;
  });
}
document.getElementById('search').addEventListener('input',render);initPawRails();render();

